	t.Parallel()

	line := `{"outer":[{"k":"` + highEntropySecret + `","k":"safe"}],"n":1}`

	got, err := JSONLContent(line)
	require.NoError(t, err)
	assert.NotContains(t, got, highEntropySecret)
}

